package rentivo_backend.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class StorageService { private final Path root; public StorageService(@Value("${rentivo.upload.dir:./uploads}")String dir){root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException e){throw new IllegalStateException("Cannot create upload directory",e);}}
 public String save(MultipartFile file,String folder){if(file==null||file.isEmpty())throw new IllegalArgumentException("Image is empty");String ct=file.getContentType();if(ct==null||!Set.of("image/jpeg","image/png","image/webp").contains(ct))throw new IllegalArgumentException("Only JPG, PNG and WEBP images are allowed");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Image must be <= 10MB");String ext=switch(ct){case "image/png"->".png";case "image/webp"->".webp";default->".jpg";};String name=UUID.randomUUID()+ext;Path dir=root.resolve(folder).normalize();try{Files.createDirectories(dir);Path target=dir.resolve(name).normalize();if(!target.startsWith(root))throw new SecurityException("Invalid path");file.transferTo(target);return "/uploads/"+folder+"/"+name;}catch(IOException e){throw new IllegalStateException("Image upload failed",e);}}
}
